definition.script:
var cronExpr = input.get('expression') || '';
var count = parseInt(input.get('count') || '5');
var fromDate = input.get('fromDate');

if (!cronExpr) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Cron expression is required');
    tags.trigger('error');
} else {
    try {
        var presets = {
            '@yearly': '0 0 1 1 *',
            '@annually': '0 0 1 1 *',
            '@monthly': '0 0 1 * *',
            '@weekly': '0 0 * * 0',
            '@daily': '0 0 * * *',
            '@midnight': '0 0 * * *',
            '@hourly': '0 * * * *'
        };
        var expr = presets[cronExpr.toLowerCase()] || cronExpr;
        var parts = expr.trim().split(/\s+/);

        if (parts.length !== 5) {
            throw new Error('Cron must have 5 fields: minute hour day month weekday');
        }

        function parseField(field, min, max) {
            var values = [];
            var segments = field.split(',');
            for (var i = 0; i < segments.length; i++) {
                var seg = segments[i];
                if (seg === '*') {
                    for (var v = min; v <= max; v++) values.push(v);
                } else if (seg.indexOf('/') > -1) {
                    var stepParts = seg.split('/');
                    var step = parseInt(stepParts[1]);
                    var start = stepParts[0] === '*' ? min : parseInt(stepParts[0]);
                    for (var v = start; v <= max; v += step) values.push(v);
                } else if (seg.indexOf('-') > -1) {
                    var rangeParts = seg.split('-');
                    for (var v = parseInt(rangeParts[0]); v <= parseInt(rangeParts[1]); v++) values.push(v);
                } else {
                    values.push(parseInt(seg));
                }
            }
            return values;
        }

        var minutes = parseField(parts[0], 0, 59);
        var hours = parseField(parts[1], 0, 23);
        var days = parseField(parts[2], 1, 31);
        var months = parseField(parts[3], 1, 12);
        var weekdays = parseField(parts[4], 0, 6);

        var start = fromDate ? new Date(fromDate) : new Date();
        if (isNaN(start.getTime())) start = new Date();

        var results = [];
        var current = new Date(start.getTime());
        current.setSeconds(0);
        current.setMilliseconds(0);
        current.setMinutes(current.getMinutes() + 1);

        var maxIterations = 100000;
        var iterations = 0;

        while (results.length < count && iterations < maxIterations) {
            iterations++;
            var m = current.getMonth() + 1;
            var d = current.getDate();
            var wd = current.getDay();
            var h = current.getHours();
            var min = current.getMinutes();

            if (months.indexOf(m) === -1) {
                current.setMonth(current.getMonth() + 1);
                current.setDate(1);
                current.setHours(0);
                current.setMinutes(0);
                continue;
            }

            var dayMatch = (parts[2] === '*' || days.indexOf(d) > -1);
            var wdMatch = (parts[4] === '*' || weekdays.indexOf(wd) > -1);
            var dayOk = (parts[2] === '*' && parts[4] === '*') || dayMatch || wdMatch;

            if (!dayOk) {
                current.setDate(current.getDate() + 1);
                current.setHours(0);
                current.setMinutes(0);
                continue;
            }

            if (hours.indexOf(h) === -1) {
                current.setHours(current.getHours() + 1);
                current.setMinutes(0);
                continue;
            }

            if (minutes.indexOf(min) === -1) {
                current.setMinutes(current.getMinutes() + 1);
                continue;
            }

            results.push(current.toISOString());
            current.setMinutes(current.getMinutes() + 1);
        }

        function describe() {
            var desc = 'At ';
            desc += parts[0] === '*' ? 'every minute' : 'minute ' + parts[0];
            desc += parts[1] === '*' ? '' : ' past hour ' + parts[1];
            if (parts[2] !== '*') desc += ' on day ' + parts[2];
            if (parts[3] !== '*') desc += ' in month ' + parts[3];
            if (parts[4] !== '*') {
                var dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
                var wdParsed = parseField(parts[4], 0, 6);
                desc += ' on ' + wdParsed.map(function(w) { return dayNames[w]; }).join(', ');
            }
            return desc;
        }

        output.set('NextRuns', json.stringify(results));
        output.set('NextRun', results.length > 0 ? results[0] : '');
        output.set('Schedule', describe());
        output.set('Expression', expr);
        output.set('IsValid', true);
        output.set('RunCount', results.length);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info('Parsed cron: ' + expr + ' - next run: ' + (results[0] || 'none'));
        tags.trigger('success');

    } catch (ex) {
        log.error('Cron parse failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('IsValid', false);
        tags.trigger('error');
    }
}
